"""Contract tests for the pre-release checklist (#657, Stage 2).

Before a non-nightly version is tagged, the Pre-release checklist
workflow (manual dispatch with the target version) opens exactly one
"Release checklist: X.Y.Z" issue, generated by
scripts/build_release_checklist.py from the previous-tag -> HEAD PR
range. The issue combines the post-release document surfaces (#394)
with the variable, adapter, registry, Docker/GHCR, Unraid and
owed-live-check sections whose absence shipped as post-release
surprises. These tests pin the generator's output (title, sections,
per-PR classification, owed-live-check collection), the workflow's
shape (dispatch-only, least-privilege GITHUB_TOKEN, opens-vs-updates),
and the rule text: fix-first items are resolved or explicitly deferred
by catduck on the issue before tagging, and nightly is exempt.
"""

import importlib.util
import json
import pathlib
import re
import subprocess
import sys
import tempfile
import unittest

import yaml

ROOT = pathlib.Path(__file__).resolve().parents[1]
WORKFLOW_PATH = ROOT / ".github" / "workflows" / "pre-release-checklist.yml"
SCRIPT_PATH = ROOT / "scripts" / "build_release_checklist.py"

spec = importlib.util.spec_from_file_location("build_release_checklist", SCRIPT_PATH)
checklist = importlib.util.module_from_spec(spec)
spec.loader.exec_module(checklist)


def load_workflow():
    return yaml.load(WORKFLOW_PATH.read_text(), Loader=yaml.BaseLoader)


def run_block():
    workflow = load_workflow()
    steps = workflow["jobs"]["checklist"]["steps"]
    return steps[-1]["run"]


def sample_range():
    """A synthetic range exercising every classification at once."""
    return {
        "version": "2.2.2",
        "from_ref": "2.2.1",
        "to_ref": "abc123",
        "repo": "catduckgnaf/print-handy",
        "prs": [
            {
                "number": 655,
                "title": "Wire every Web UI setting",
                "labels": ["enhancement"],
                "body": "All surfaces verified offline.\n"
                        "- Live checks: first live print on the AD5X is still owed.\n",
                "files": [
                    {"filename": "print_handy/settings.py", "status": "modified"},
                    {"filename": "print_handy/webui/catalog.py", "status": "modified"},
                    {"filename": ".env.example", "status": "modified"},
                    {"filename": "docs/SETTINGS.md", "status": "modified"},
                ],
            },
            {
                "number": 660,
                "title": "New printer adapter",
                "labels": [],
                "body": "Offline adapter tests pass.",
                "files": [
                    {"filename": "print_handy/printers/example/adapter.py",
                     "status": "added"},
                    {"filename": "print_handy/data/printers-registry/example.toml", "status": "added"},
                    {"filename": "docs/PRINTER-SUPPORT.md", "status": "modified"},
                ],
            },
            {
                "number": 661,
                "title": "Remove the legacy guide",
                "labels": ["documentation"],
                "body": "",
                "files": [
                    {"filename": "docs/LEGACY.md", "status": "removed"},
                    {"filename": "Dockerfile", "status": "modified"},
                    {"filename": "docker/unraid/print-handy.xml", "status": "modified"},
                ],
            },
            {
                "number": 662,
                "title": "Docs wording only",
                "labels": ["documentation"],
                # Template boilerplate in an HTML comment must not be
                # collected as an owed live check.
                "body": "<!-- Live verification still owed: fill this in -->\n"
                        "Wording verified against the guide.",
                "files": [
                    {"filename": "docs/SETUP.md", "status": "modified"},
                ],
            },
        ],
    }


class GeneratorBodyContract(unittest.TestCase):
    def setUp(self):
        self.title, self.body = checklist.build_checklist(sample_range())

    def test_title_is_release_checklist_version(self):
        self.assertEqual(self.title, "Release checklist: 2.2.2")
        self.assertIn("## Release checklist: 2.2.2", self.body)
        self.assertIn("`2.2.1...abc123`", self.body)
        self.assertIn("not yet tagged", self.body)

    def test_every_section_is_present(self):
        for heading in (
            "## Fix-first vs defer",
            "## Merged PRs in this range",
            "## Document and GitHub surfaces",
            "## Variables in this range (fix-first)",
            "## Adapters and connections in this range (fix-first)",
            "## Registry and docs matrices (fix-first)",
            "## Docker and GHCR (fix-first)",
            "## Unraid templates (fix-first)",
            "## Owed live checks",
            "## Slicing-speed baselines (fix-first)",
            "## Fix-first gate",
        ):
            self.assertIn(heading, self.body)

    def test_document_surfaces_match_the_post_release_seven(self):
        for surface in (
            "print-handy/docs",
            "Pages site",
            "Wiki",
            "README + repo About",
            "Release notes",
            "Discord-facing surfaces",
        ):
            self.assertIn(surface, self.body)
        self.assertIn("verified-no-change", self.body)

    def test_fix_first_rule_and_nightly_exemption_are_stated(self):
        self.assertIn(
            "every **fix-first** item below is resolved or "
            "explicitly deferred by catduck",
            self.body,
        )
        self.assertIn("Nightly builds are exempt", self.body)
        self.assertIn("manual-dispatch only", self.body)
        # Items are checkboxes throughout.
        self.assertGreaterEqual(self.body.count("- [ ]"), 12)

    def test_unraid_section_names_both_repos(self):
        section = self.body.split("## Unraid templates")[1].split("## ")[0]
        self.assertIn("docker/unraid/print-handy.xml", section)
        self.assertIn("catduck-unraid-templates", section)

    def test_speed_baseline_section_is_the_734_release_step(self):
        section = self.body.split("## Slicing-speed baselines")[1].split("\n## ")[0]
        for needle in ("tests/README.md", "tests/corpus/timing_baseline.json",
                       "tests/corpus/timing_baseline_real_slicer.json", "discord-timing",
                       "slicer-timing-real", "`reason`", "--recorded-from", "2.2.2 release commit",
                       "record the outcome on #734"):
            self.assertIn(needle, section)
        self.assertEqual(section.count("- [ ]"), 3)

    def test_docker_section_covers_candidate_run_and_ghcr(self):
        section = self.body.split("## Docker and GHCR")[1].split("## ")[0]
        self.assertIn("publish=false", section)
        self.assertIn("GHCR", section)
        self.assertIn("`:2.2.2`", section)

    def test_generation_is_deterministic(self):
        again = checklist.build_checklist(sample_range())
        self.assertEqual((self.title, self.body), again)


class GeneratorNullLabels(unittest.TestCase):
    def test_null_labels_render_as_no_labels(self):
        data = sample_range()
        data["prs"][0]["labels"] = None
        _, body = checklist.build_checklist(data)
        self.assertIn("#655", body)


class GeneratorClassification(unittest.TestCase):
    def setUp(self):
        _, self.body = checklist.build_checklist(sample_range())

    def section(self, heading):
        return self.body.split(heading)[1].split("\n## ")[0]

    def test_settings_touching_pr_lands_in_variables_section(self):
        variables = self.section("## Variables in this range")
        self.assertIn("#655", variables)
        self.assertIn("`print_handy/settings.py`", variables)
        self.assertIn("`print_handy/webui/catalog.py`", variables)
        self.assertIn("`.env.example`", variables)
        # The verdict surfaces the section demands.
        for surface in ("defaults tree", "OPTIONAL_KEYS", "Web UI catalog",
                        "consuming code", "docs/SETTINGS.md", "Unraid"):
            self.assertIn(surface, variables)

    def test_printers_touching_pr_lands_in_adapters_and_registry(self):
        adapters = self.section("## Adapters and connections")
        self.assertIn("#660", adapters)
        self.assertIn("printer-scope", adapters)
        registry = self.section("## Registry and docs matrices")
        self.assertIn("#660", registry)
        self.assertIn("MACROS.md", registry)
        self.assertIn("PRINTER-SUPPORT.md", registry)

    def test_docs_only_pr_appears_in_no_fix_first_pr_list(self):
        for heading in ("## Variables in this range",
                        "## Adapters and connections",
                        "## Registry and docs matrices"):
            self.assertNotIn("#662", self.section(heading))

    def test_docker_and_unraid_sections_list_their_prs(self):
        self.assertIn("#661", self.section("## Docker and GHCR"))
        self.assertIn("#661", self.section("## Unraid templates"))

    def test_removed_docs_page_is_a_page_removal(self):
        prs_section = self.section("## Merged PRs in this range")
        self.assertIn("PAGE REMOVAL: docs/LEGACY.md", prs_section)
        self.assertIn("**Page removals in this range:** docs/LEGACY.md",
                      prs_section)

    def test_pr_table_uses_post_release_hints(self):
        prs_section = self.section("## Merged PRs in this range")
        self.assertIn("docs guide", prs_section)
        self.assertIn("Unraid CA template (release-time sync: verify)",
                      prs_section)
        self.assertIn("| #655 | Wire every Web UI setting | enhancement |",
                      prs_section)


class OwedLiveChecks(unittest.TestCase):
    def test_owed_line_is_collected_with_its_pr(self):
        _, body = checklist.build_checklist(sample_range())
        owed = body.split("## Owed live checks")[1].split("## ")[0]
        self.assertIn("#655", owed)
        self.assertIn("first live print on the AD5X is still owed", owed)

    def test_template_comment_is_not_collected(self):
        _, body = checklist.build_checklist(sample_range())
        owed = body.split("## Owed live checks")[1].split("## ")[0]
        self.assertNotIn("#662", owed)
        self.assertNotIn("fill this in", owed)

    def test_no_owed_lines_leaves_a_standing_subsection(self):
        data = sample_range()
        data["prs"] = [pr for pr in data["prs"] if pr["number"] != 655]
        _, body = checklist.build_checklist(data)
        owed = body.split("## Owed live checks")[1].split("## ")[0]
        self.assertIn("No PR body in this range names an owed live check",
                      owed)
        self.assertIn("explicitly deferred by catduck", owed)

    def test_owed_detection_patterns(self):
        cases = {
            "Hardware verification is still owed.": True,
            "Live check not run: no printer on the bench.": True,
            "The live timelapse check is unverified on real hardware.": True,
            "Owed: one live print once the printer is free.": True,
            "Live checks passed on the AD5X.": False,
            "All hardware paths tested offline with fakes.": False,
        }
        for line, expected in cases.items():
            with self.subTest(line=line):
                found = checklist.owed_live_checks({"body": line})
                self.assertEqual(bool(found), expected)


class GeneratorCli(unittest.TestCase):
    def run_cli(self, data):
        """Run the generator CLI; return (proc, body_text, title_text)."""
        with tempfile.TemporaryDirectory() as tmp:
            tmp = pathlib.Path(tmp)
            src = tmp / "range.json"
            src.write_text(json.dumps(data))
            out = tmp / "body.md"
            title_out = tmp / "title.txt"
            proc = subprocess.run(
                [sys.executable, str(SCRIPT_PATH), "--input", str(src),
                 "--output", str(out), "--title-output", str(title_out)],
                capture_output=True, text=True,
            )
            body_text = out.read_text() if out.exists() else ""
            title_text = title_out.read_text() if title_out.exists() else ""
            return proc, body_text, title_text

    def test_cli_writes_body_and_title(self):
        proc, body_text, title_text = self.run_cli(sample_range())
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(title_text.strip(), "Release checklist: 2.2.2")
        self.assertIn("## Owed live checks", body_text)

    def test_cli_rejects_a_malformed_version(self):
        data = sample_range()
        data["version"] = "2.2"
        proc, _, _ = self.run_cli(data)
        self.assertEqual(proc.returncode, 2)
        self.assertIn("MAJOR.MINOR.PATCH", proc.stderr)

    def test_cli_rejects_a_missing_range_start(self):
        data = sample_range()
        data["from_ref"] = ""
        proc, _, _ = self.run_cli(data)
        self.assertEqual(proc.returncode, 2)


class PreReleaseWorkflowContract(unittest.TestCase):
    def test_trigger_is_dispatch_only_with_version_and_from_inputs(self):
        workflow = load_workflow()
        self.assertEqual(sorted(workflow["on"]), ["workflow_dispatch"])
        inputs = workflow["on"]["workflow_dispatch"]["inputs"]
        self.assertEqual(sorted(inputs), ["from", "version"])
        self.assertEqual(inputs["version"]["type"], "string")
        self.assertEqual(inputs["version"]["required"], "true")
        self.assertEqual(inputs["from"]["required"], "false")

    def test_permissions_are_least_privilege_github_token_only(self):
        workflow = load_workflow()
        self.assertEqual(
            workflow["permissions"],
            {"contents": "read", "issues": "write", "pull-requests": "read"},
        )
        for job in workflow["jobs"].values():
            self.assertNotIn("permissions", job)
        text = WORKFLOW_PATH.read_text()
        self.assertIn("${{ github.token }}", text)
        # No secrets at all: the checklist uses only the GITHUB_TOKEN.
        self.assertEqual(set(re.findall(r"secrets\.([A-Z_]+)", text)), set())

    def test_range_is_latest_release_tag_to_head(self):
        run = run_block()
        self.assertIn('releases?per_page=1', run)
        self.assertIn('compare/$from_ref...$TO_REF', run)
        self.assertIn("github.sha", WORKFLOW_PATH.read_text())

    def test_issue_numbers_in_subjects_are_skipped_not_fatal(self):
        run = run_block()
        self.assertIn('if ! gh api "repos/$repo/pulls/$n" > pr.json; then', run)
        self.assertIn("is not a pull request", run)
        self.assertIn("continue", run)

    def test_generator_builds_the_body(self):
        run = run_block()
        self.assertIn("scripts/build_release_checklist.py", run)
        self.assertIn("--title-output title.txt", run)
        self.assertIn('issue_title="$(cat title.txt)"', run)

    def test_opens_or_updates_exactly_one_issue(self):
        run = run_block()
        # The open-issue lookup by the generated title must precede
        # creation, so a re-dispatch updates instead of duplicating.
        self.assertLess(run.index("issue list"), run.index("issue create"))
        self.assertIn("issue comment", run)
        self.assertIn('select(.title == $t)', run)

    def test_checklist_lookup_searches_all_states_by_title(self):
        # P2-153 / P2-263: the lookup must search by title across ALL issue
        # states before the --limit applies. --state open misses the
        # checklist once it is closed; an unfiltered list misses it once
        # more than 100 newer issues exist — either way a re-run duplicates.
        text = WORKFLOW_PATH.read_text()
        lookups = [line for line in text.splitlines() if "gh issue list" in line]
        self.assertEqual(len(lookups), 1)
        self.assertIn("--state all", lookups[0])
        self.assertNotIn("--state open", lookups[0])
        self.assertIn('--search "in:title \\"$issue_title\\""', text)

    def test_nightly_is_never_a_trigger(self):
        workflow = load_workflow()
        on = workflow["on"]
        self.assertNotIn("schedule", on)
        self.assertNotIn("release", on)
        self.assertNotIn("push", on)


if __name__ == "__main__":
    unittest.main()
